-- NFL 2026 remaining games. Search keys find a team. Kickoff is Pacific; phones shift it.
-- TBD games have a day and no clock, until a later list update sets the time.

alter table public.shared_lists
  add column if not exists search_keys text[] not null default '{}';

alter table public.shared_lists
  add column if not exists time_zone text;

alter table public.shared_lists
  drop constraint if exists shared_lists_search_keys;

alter table public.shared_lists
  add constraint shared_lists_search_keys check (cardinality(search_keys) <= 20);

alter table public.shared_lists
  drop constraint if exists shared_lists_time_zone;

alter table public.shared_lists
  add constraint shared_lists_time_zone check (
    time_zone is null
    or time_zone ~ '^[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)*$'
  );

create index if not exists shared_lists_search_keys_idx
  on public.shared_lists using gin (search_keys);

on conflict (id) do nothing;

on conflict (id) do nothing;
